import setData from '../data/content/item-sets.json';
import type { BuildEquipmentState } from '../types';
import { equippedSlot3 } from '../types';

// Generated by `scripts/build-set-data.mjs`. Set bonuses stay prose; few map to a calculator channel.

export interface SetThreshold {
  count: number;
  description: string;
}

export interface ItemSet {
  members: string[];
  thresholds: SetThreshold[];
  /** For a set that scales per piece instead of at thresholds. */
  note?: string;
}

export const ITEM_SETS = setData as Record<string, ItemSet>;

const SET_OF_ITEM = new Map<string, string[]>();
for (const [name, set] of Object.entries(ITEM_SETS)) {
  for (const member of set.members) {
    SET_OF_ITEM.set(member, [...(SET_OF_ITEM.get(member) ?? []), name]);
  }
}

export function setsForItem(itemName: string | null | undefined): string[] {
  if (!itemName) return [];
  return SET_OF_ITEM.get(itemName) ?? [];
}

export interface ActiveSet {
  name: string;
  equipped: number;
  total: number;
  active: SetThreshold[];
  upcoming: SetThreshold[];
  note?: string;
}

export function equippedItemNames(equipment: BuildEquipmentState | undefined): string[] {
  if (!equipment) return [];
  const usingOffHand = equippedSlot3(equipment) === 'offHandWeapon';
  return [
    equipment.primaryWeapon?.selectedWeaponName,
    equipment.armorName,
    usingOffHand ? equipment.offHandWeapon?.selectedWeaponName : equipment.hands?.itemName,
    equipment.legs?.itemName,
    equipment.accessory1?.itemName,
    equipment.accessory2?.itemName,
  ].filter((name): name is string => Boolean(name));
}

export function setPiecesEquipped(
  equipment: BuildEquipmentState | undefined,
  setName: string,
): number {
  const members = new Set(ITEM_SETS[setName]?.members ?? []);
  if (!members.size) return 0;
  return equippedItemNames(equipment).filter(name => members.has(name)).length;
}

export function activeSets(equipment: BuildEquipmentState | undefined): ActiveSet[] {
  const equipped = equippedItemNames(equipment);
  if (!equipped.length) return [];

  const counts = new Map<string, number>();
  for (const item of equipped) {
    for (const name of setsForItem(item)) counts.set(name, (counts.get(name) ?? 0) + 1);
  }

  return [...counts.entries()]
    .map(([name, count]) => {
      const set = ITEM_SETS[name];
      return {
        name,
        equipped: count,
        total: set.members.length,
        active: set.thresholds.filter(threshold => count >= threshold.count),
        upcoming: set.thresholds.filter(threshold => count < threshold.count),
        ...(set.note ? { note: set.note } : {}),
      };
    })
    .sort((a, b) => b.active.length - a.active.length || a.name.localeCompare(b.name));
}
